<?php $rows=$pdo->query('SELECT u.username,a.attendance_date,a.attendance_time FROM attendance a JOIN users u ON u.id=a.user_id ORDER BY a.attendance_date DESC,a.attendance_time DESC')->fetchAll(); ?><section class="glass-card"><h2>Rekod Kehadiran</h2><p class="muted">Senarai kehadiran yang direkodkan oleh sistem.</p><div class="table-responsive"><table class="table table-dark table-hover"><thead><tr><th>Nama</th><th>Tarikh</th><th>Masa</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['username'])?></td><td><?=e($r['attendance_date'])?></td><td><?=e($r['attendance_time'])?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="3" class="text-center muted">Belum ada rekod kehadiran.</td></tr><?php endif; ?></tbody></table></div></section>